var originals=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VRC.SDK3.Avatars.Components.VRCAvatarDescriptor>(true)).Where(a=>a.name=="MANUKA_lilToon"||a.name=="Milltina"||a.name=="rurune_None").ToArray();if(originals.Length!=3)throw new System.Exception("Avatar set changed");var results=new List<object>();foreach(var original in originals){var expected=LumaKroma.Sps2SetupAssistant.Editor.Generation.FullSetupGenerator.Find(original).sockets.Single(s=>s.id=="chest").pose;var pos=expected.position;var rot=expected.rotation;var clone=UnityEngine.Object.Instantiate(original.gameObject);clone.name="ChestAdoptionProbe";try{var avatar=clone.GetComponent<VRC.SDK3.Avatars.Components.VRCAvatarDescriptor>();var root=LumaKroma.Sps2SetupAssistant.Editor.Generation.FullSetupGenerator.Find(avatar);var settings=root.settings.Copy();string error;if(!LumaKroma.Sps2SetupAssistant.Editor.Generation.FullSetupGenerator.Apply(avatar,settings,true,out root,out error))throw new System.Exception(error);var chest=root.sockets.Single(s=>s.id=="chest").pose;float delta=UnityEngine.Vector3.Distance(chest.position,pos);float angle=UnityEngine.Quaternion.Angle(chest.rotation,rot);if(delta>1e-5f||angle>.01f)throw new System.Exception(original.name+" trial mismatch "+delta+" angle "+angle);var generated=chest.position;chest.position+=avatar.transform.forward*.001f;var manual=chest.position;if(!LumaKroma.Sps2SetupAssistant.Editor.Generation.FullSetupGenerator.Apply(avatar,settings,false,out root,out error))throw new System.Exception(error);if(root.sockets.Single(s=>s.id=="chest").pose.position!=manual)throw new System.Exception("Nonreplacement moved manual pose");results.Add(new{avatar=original.name,position=original.transform.InverseTransformPoint(generated).ToString("F5"),acceptedTrialDelta=delta,angleDelta=angle,manualPreserved=true,originalUnchanged=expected.position==pos&&expected.rotation==rot});}finally{UnityEditor.Undo.FlushUndoRecordObjects();foreach(var t in clone.GetComponentsInChildren<UnityEngine.Transform>(true)){foreach(var c in t.GetComponents<UnityEngine.Component>())if(c!=null)UnityEditor.Undo.ClearUndo(c);UnityEditor.Undo.ClearUndo(t.gameObject);}UnityEngine.Object.DestroyImmediate(clone);}}return results;
